<script lang="ts">
  import {refreshAll} from '$app/navigation';
  import {command,request,display} from '#lib/client/api.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  import Status from './Status.svelte';
  let {data,configured=false}:{data:AppData;configured?:boolean}=$props();
  let password=$state('');let busy=$state(false);let error=$state('');let notice=$state('');
  let resolving:Row|null=$state(null);let actualCost=$state(''),reconciliationReason=$state(''),reconciliationPassword=$state(''),receiptConfirmed=$state(false);
  const usage=$derived((data.related?.ai_usage as unknown as Row)||{});
  const budget=$derived(usage.budget||{});
  const capabilities=$derived(Array.isArray(usage.capabilities)?usage.capabilities:[]);
  const unsettled=$derived(Array.isArray(usage.unsettled)?usage.unsettled:[]);
  const names:Record<string,string>={assistant_reasoning:'Assistent & Planprüfung',speech_transcription:'Spracheingabe',image_generation:'KI-Visualisierung'};
  function amount(value:unknown){return value===null||value===undefined||value===''||!Number.isFinite(Number(value))?'Noch nicht abgerechnet':new Intl.NumberFormat('de-DE',{style:'currency',currency:'USD',minimumFractionDigits:4,maximumFractionDigits:6}).format(Number(value));}
  function count(value:unknown){return value===null||value===undefined?'Noch nicht bestätigt':new Intl.NumberFormat('de-DE').format(Number(value));}
  const remaining=$derived(budget.limit_amount!==undefined&&budget.spent!==undefined&&budget.reserved!==undefined?Math.max(0,Number(budget.limit_amount)-Number(budget.spent)-Number(budget.reserved)):null);
  async function test(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';notice='';try{await request('/api/v1/reauth',{password});await command('integrations.openai.test',undefined,{});password='';notice='Eine kleine Prüfung mit dem gespeicherten Standardmodell wurde eingereiht. Sie verwendet synthetische Daten und das freigegebene Kostenlimit. Das tatsächliche Ergebnis finden Sie unter Verarbeitung.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Modellprüfung konnte nicht gestartet werden.';}finally{busy=false;}}
  function beginReconciliation(row:Row){resolving=row;actualCost='';reconciliationReason='';reconciliationPassword='';receiptConfirmed=false;error='';notice='';}
  async function reconcile(event:SubmitEvent){event.preventDefault();if(!resolving||!receiptConfirmed||busy)return;const run=resolving;busy=true;error='';notice='';try{await request('/api/v1/reauth',{password:reconciliationPassword});await command('integrations.openai.usage.resolve',undefined,{run_id:run.id,actual_cost:actualCost.replace(',','.'),reason:reconciliationReason});resolving=null;reconciliationPassword='';notice='Der belegte tatsächliche Verbrauch wurde abgeglichen und die zugehörige Reservierung aufgelöst.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die offenen Kosten konnten nicht abgeglichen werden.';}finally{busy=false;}}
</script>
<section class="panel mt" aria-labelledby="ai-usage-title">
  <header class="panel-header"><div><h2 id="ai-usage-title">KI-App-Messwerte & Kostenkontrolle</h2><p>{budget.period||'Aktueller Monat'} · Beträge in USD. Reservierungen sind noch keine endgültige Abrechnung.</p></div><a class="btn small" href="/jobs">Verarbeitung öffnen<Icon name="arrow" size={14}/></a></header>
  <div class="panel-body"><dl class="definition-list"><div><dt>Freigegebenes Monatsbudget</dt><dd>{amount(budget.limit_amount)}</dd></div><div><dt>Bestätigte tatsächliche Kosten</dt><dd>{amount(budget.spent)}</dd></div><div><dt>Für offene Aufrufe reserviert</dt><dd>{amount(budget.reserved)}</dd></div><div><dt>Noch nicht gebundenes Budget</dt><dd>{amount(remaining)}</dd></div></dl><p class="field-help mt">Ein unklarer Ausgang bleibt reserviert, bis die Abrechnung geklärt ist. Die Suite startet keine automatische teurere Ersatzanfrage. Die App-Messwerte enthalten nur Aufrufe dieser Suite. Maßgeblich bleibt die <a class="text-link" href="https://platform.openai.com/usage" target="_blank" rel="noreferrer">Verbrauchsübersicht Ihres OpenAI-Projekts</a>.</p></div>
  {#if capabilities.length}<div class="table-scroll"><table class="data-table"><caption class="sr-only">KI-Nutzung des aktuellen Monats je Funktion und tatsächlichem Modell</caption><thead><tr><th>Funktion / Modell</th><th class="number">Anfragen</th><th class="number">Eingabetokens</th><th class="number">Ausgabetokens</th><th class="number">Abgerechnete Kosten</th></tr></thead><tbody>{#each capabilities as row}<tr><th scope="row">{names[row.capability]||'KI-Funktion'}<span class="record-subtitle">{row.model_id}</span></th><td class="number">{count(row.requests)}</td><td class="number">{count(row.input_tokens)}</td><td class="number">{count(row.output_tokens)}</td><td class="number">{amount(row.actual_cost)}</td></tr>{/each}</tbody></table></div>{:else}<div class="panel-body" style="padding-top:0"><p class="small">Für diesen Monat sind noch keine KI-Aufrufe im berechtigten Bestand erfasst.</p></div>{/if}
  {#if unsettled.length}<div class="panel-body"><h3 class="small">Offene oder noch ungeklärte Aufrufe</h3>{#each unsettled as row}<article class="ai-unsettled"><div><strong>{names[row.capability]||'KI-Funktion'} · {row.model_id}</strong><p>{display(row.created_at,'created_at')} · reservierte Obergrenze {amount(row.cost_reserved)}</p></div><Status value={row.status}/>{#if ['outcome_unknown','cost_review'].includes(row.status)}<button class="btn small" disabled={busy} onclick={()=>beginReconciliation(row)}>Anbieterbeleg abgleichen</button>{/if}</article>{/each}<p class="field-help mt">Diese Kosten sind nicht als null verbucht. Prüfen Sie unklare Aufrufe im Anbieterprojekt und im Verarbeitungsnachweis, bevor Sie dieselbe Aufgabe erneut kostenpflichtig starten.</p></div>{/if}
  {#if resolving}<form class="panel-body ai-reconciliation" onsubmit={reconcile}><h3>Belegte Kosten eines ungeklärten Aufrufs</h3><p class="small mt">{resolving.model_id} · gestartet {display(resolving.created_at,'created_at')}. Gleichen Sie den konkreten Aufruf mit dem tatsächlichen Nachweis im Anbieterprojekt ab.</p><div class="field-grid mt"><div class="field"><label for="ai-actual-cost">Belegte tatsächliche Kosten · USD *</label><input id="ai-actual-cost" inputmode="decimal" bind:value={actualCost} required pattern="[0-9]+([,.][0-9]+)?"/><span class="field-help">Null nur eintragen, wenn der Anbieter für genau diesen Aufruf keine Kosten bestätigt hat. Eine fehlende Antwort ist kein Kostenbeleg.</span></div><div class="field full"><label for="ai-reconciliation-reason">Anbieterbeleg und konkrete Prüfergebnisse *</label><textarea id="ai-reconciliation-reason" bind:value={reconciliationReason} required minlength="20" placeholder="Belegdatum, Projekt, konkrete Anfrage und bestätigter Verbrauch"></textarea></div><label class="check-field full"><input type="checkbox" bind:checked={receiptConfirmed} required/><span>Ich habe den Anbieterbeleg für diesen konkreten Aufruf kontrolliert. Der eingetragene Betrag ist tatsächlich bestätigt.</span></label><div class="field full"><label for="ai-reconciliation-password">Eigene Passphrase erneut bestätigen *</label><input id="ai-reconciliation-password" type="password" bind:value={reconciliationPassword} autocomplete="current-password" required/></div></div><div class="inline-actions mt"><button class="btn" type="button" disabled={busy} onclick={()=>resolving=null}>Zurück</button><button class="btn primary" disabled={busy||!receiptConfirmed}>Belegten Verbrauch verbindlich abgleichen</button></div>{#if error}<p class="field-error mt" role="alert">{error}</p>{/if}</form>{/if}
  <form class="ai-test-form" onsubmit={test}><div><h3>Verbindung praktisch prüfen</h3><p class="small">Startet bewusst genau eine kleine Anfrage mit dem gespeicherten Standardmodell. Dafür gelten die zuvor gespeicherten USD-Kostenlimits.</p>{#if error}<p class="field-error mt" role="alert">{error}</p>{/if}{#if notice}<p class="field-help mt" role="status">{notice}</p>{/if}<div class="field mt"><label for="ai-test-password">Ihr eigenes Suite-Passwort bestätigen *</label><input id="ai-test-password" type="password" autocomplete="current-password" bind:value={password} required/></div></div><button class="btn" disabled={busy||!configured}><Icon name={busy?'refresh':'spark'} size={15} class={busy?'spin':''}/>{busy?'Wird eingereiht …':'Kleine Modellprüfung starten'}</button></form>
</section>
<style>.ai-unsettled{display:flex;gap:20px;justify-content:space-between;align-items:flex-start;margin-top:20px;padding-top:20px;border-top:1px solid var(--line)}.ai-unsettled strong{font-size:13px;font-weight:550}.ai-unsettled p{font-size:12px;margin-top:6px}.ai-test-form{border-top:1px solid var(--line);padding:26px 28px;background:var(--wash);display:flex;gap:26px;align-items:flex-end}.ai-test-form>div{flex:1;max-width:65ch}.ai-test-form h3{font-size:14px;font-weight:550}.ai-test-form p{margin-top:8px}.ai-test-form .btn{flex:none}@media(max-width:760px){.ai-test-form{padding:24px 20px;flex-direction:column;align-items:stretch}.ai-unsettled{flex-wrap:wrap}.ai-unsettled p{font-size:13px}}.ai-reconciliation{border-top:1px solid var(--line)}.ai-reconciliation h3{font-size:16px;font-weight:550}.ai-unsettled .btn{white-space:normal;max-width:150px}</style>
